// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        // caller must be someone other than the admin (admin = deployer = this contract)
        vm.assume(caller != address(this));

        // admin installs `caller` as the (non-admin) owner
        vm.prank(address(this));
        c.setOwner(caller);

        // a non-admin caller (even the current owner) must NOT be able to change ownership
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        assertTrue(!ok && c.owner() == caller);
    }
}
